  /* Nav */
  nav {
    background: var(--primary);
    position: sticky;
    top: 0;
    z-index: 100;
    box-shadow: 0 2px 8px rgba(0,0,0,0.15);
  }
  nav ul {
    list-style: none;
    display: flex;
    overflow-x: auto;
    max-width: 1100px;
    margin: 0 auto;
    padding: 0 1rem;
    scrollbar-width: none;
  }
  nav ul::-webkit-scrollbar { display: none; }
  nav li { flex-shrink: 0; }
  nav a {
    display: block;
    padding: 0.75rem 1rem;
    color: rgba(255,255,255,0.7);
