    border-bottom: 3px solid transparent;
    white-space: nowrap;
  }
  nav a:hover, nav a.active {
    color: white;
    border-bottom-color: var(--accent);
  }

  /* Sections */
  section {
    background: var(--surface);
    border-radius: 10px;
    padding: 2rem;
    margin-bottom: var(--section-gap);
