  }
  .kpi-value {
    font-size: 2rem;
    font-weight: 800;
    color: var(--primary);
    line-height: 1.1;
  }
  .kpi-label {
    font-size: 0.78rem;
    color: var(--text-muted);
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-top: 0.2rem;
  }
  .kpi-sub { font-size: 0.75rem; color: var(--text-muted); margin-top: 0.2rem; }

  /* Tables */
  table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.88rem;
    margin-bottom: 1rem;
  }
  th {
    background: var(--primary);
    color: white;
    padding: 0.6rem 0.75rem;
    text-align: left;
    font-weight: 700;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }
  td {
    padding: 0.55rem 0.75rem;
    border-bottom: 1px solid var(--border);
  }
  tr:last-child td { border-bottom: none; }
  tr:nth-child(even) { background: #f8fafc; }
  tr:hover { background: #eef2f7; }
  .num { text-align: center; font-variant-numeric: tabular-nums; }
  .mcq-c { color: var(--mcq); font-weight: 700; }
  .short-c { color: var(--short); font-weight: 700; }
  .long-c { color: var(--long); font-weight: 700; }

  /* Chart containers */
  .chart-row { display: grid; grid-template-columns: 1fr 1fr; gap: 1.5rem; margin-bottom: 1.5rem; }
  .chart-row.full { grid-template-columns: 1fr; }
  .chart-card {
    background: var(--bg);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 1.25rem;
  }
  .chart-card h4 {
    font-size: 0.82rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.07em;
    color: var(--text-muted);
    margin-bottom: 0.75rem;
  }
  .chart-wrap { position: relative; height: 280px; }
  .chart-wrap.tall { height: 340px; }
  .chart-wrap.short-h { height: 220px; }

  /* Insight callout */
  .callout {
    background: #fff8f0;
    border-left: 4px solid var(--accent);
    border-radius: 0 6px 6px 0;
