    background: #eff6ff;
    border-left-color: var(--mcq);
  }
  .callout.green {
    background: #f0fdf4;
    border-left-color: var(--long);
  }
  .callout-title {
    font-weight: 700;
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--accent);
    margin-bottom: 0.3rem;
  }

  /* Tags */
  .tag {
    display: inline-block;
    background: var(--primary);
    color: white;
    font-size: 0.7rem;
    padding: 0.15rem 0.55rem;
    border-radius: 4px;
    margin: 0.15rem 0.1rem;
    font-weight: 600;
  }
  .tag.mcq-tag { background: var(--mcq); }
  .tag.short-tag { background: var(--short); }
  .tag.long-tag { background: var(--long); }

  /* Progress bars */
  .bar-row { display: flex; align-items: center; gap: 0.75rem; margin: 0.4rem 0; font-size: 0.85rem; }
