  .bar-fill.mcq { background: var(--mcq); }
  .bar-fill.short { background: var(--short); }
  .bar-fill.long { background: var(--long); }
  .bar-val { min-width: 40px; text-align: right; font-weight: 700; font-size: 0.82rem; color: var(--text); }

  /* Recommendation cards */
  .rec-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; margin-top: 1rem; }
  .rec-card {
    background: var(--bg);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 1rem 1.1rem;
    border-top: 3px solid var(--primary);
