    display: inline-block;
    width: 22px; height: 22px;
    background: var(--primary);
    color: white;
    border-radius: 50%;
    text-align: center;
    line-height: 22px;
    font-size: 0.72rem;
    font-weight: 700;
    margin-right: 0.4rem;
